/// <reference path="./.sst/platform/config.d.ts" />

/**
 * InvAI on AWS. Repos are siblings of this one: ../invai-backend, ../invai-imaging,
 * ../invai-web, ../invai-floor. Written and typechecked against the installed sst@4.17.1
 * (component sources under `.sst/platform/src/components`, generated by `sst install`) —
 * check that directory before changing component options rather than guessing from docs
 * written for other SST versions.
 *
 * `sst deploy` needs AWS credentials, which this environment does not have. Typecheck with
 * `pnpm typecheck`; a real deploy is unverified.
 */
export default $config({
  app(input) {
    return {
      name: "invai",
      home: "aws",
      removal: input?.stage === "production" ? "retain" : "remove",
      protect: input?.stage === "production",
    };
  },
  async run() {
    const isProd = $app.stage === "production";

    // Cheap NAT instance instead of NAT gateways (~$30/mo saved).
    const vpc = new sst.aws.Vpc("Vpc", { nat: "ec2" });

    // RDS Postgres 17. Encrypted at rest by default (the component sets storageEncrypted:
    // true), private subnets only (no public prop set). RDS Proxy is optional; on for prod
    // to pool connections from services that scale out.
    //
    // NOTE: this only provisions the master (owner) user. Local dev creates a second,
    // low-privilege `invai_app` role with RLS enforced (see local/init.sql) — nothing here
    // does that in RDS yet. Until a bootstrap step (a one-time SQL script run against the
    // instance, e.g. from a deploy job or an SST dynamic provider) creates `invai_app` the
    // same way, DATABASE_URL below points at the owner user for both app and migrations.
    const db = new sst.aws.Postgres("Db", {
      vpc,
      version: "17",
      proxy: isProd,
    });

    // Valkey (Redis-API-compatible), matching the local docker-compose valkey/valkey image.
    const redis = new sst.aws.Redis("Redis", { vpc, engine: "valkey" });

    // Design files, rendered sheets, labels, mockups, raw payload archives. Private (no
    // `access` set), signed URLs. Lifecycle matches architecture.md §7: rendered sheets
    // expire after 90 days, raw payload archives after 30.
    const files = new sst.aws.Bucket("Files", {
      lifecycle: [
        { id: "expire-sheets", prefix: "sheets/", expiresIn: "90 days" },
        { id: "expire-raw", prefix: "raw/", expiresIn: "30 days" },
      ],
    });

    // Field-level encryption for buyer PII (names, addresses, emails) and OAuth tokens
    // (architecture.md §7, §11).
    const fieldEncryptionKmsKey = new aws.kms.Key("FieldEncryptionKey", {
      description: "InvAI field-level encryption for buyer PII and OAuth tokens",
      enableKeyRotation: true,
    });

    // Placeholder SES identity for vendor and invite emails (architecture.md §10). Swap
    // SES_DOMAIN for the real sending domain and verify it (DNS records SES gives you)
    // before sending; new accounts start in the SES sandbox until production access is
    // requested.
    new aws.sesv2.EmailIdentity("Email", {
      emailIdentity: process.env.SES_DOMAIN ?? `${$app.stage}.invai.example`,
    });

    // Secrets: `sst secret set <Name> <value> --stage <stage>` before first deploy.
    // BetterAuthSecret and FieldEncryptionKey are required (no placeholder — deploy fails
    // loudly if unset). The rest are optional integrations that fall back to a mock/sandbox
    // provider when empty, same as local dev (see CLAUDE.md).
    const betterAuthSecret = new sst.Secret("BetterAuthSecret");
    const fieldEncryptionKey = new sst.Secret("FieldEncryptionKey");
    const anthropicApiKey = new sst.Secret("AnthropicApiKey", "");
    const easyPostApiKey = new sst.Secret("EasyPostApiKey", "");
    const shopifyApiKey = new sst.Secret("ShopifyApiKey", "");
    const shopifyApiSecret = new sst.Secret("ShopifyApiSecret", "");

    const secrets = [
      betterAuthSecret,
      fieldEncryptionKey,
      anthropicApiKey,
      easyPostApiKey,
      shopifyApiKey,
      shopifyApiSecret,
    ];

    const databaseUrl = $interpolate`postgres://${db.username}:${db.password}@${db.host}:${db.port}/${db.database}`;
    // ElastiCache Redis/Valkey clusters from this component require TLS + AUTH.
    const redisUrl = $interpolate`rediss://${redis.username}:${redis.password}@${redis.host}:${redis.port}`;

    const cluster = new sst.aws.Cluster("Cluster", { vpc });

    // Internal only: no loadBalancer/public endpoint. Reached by api/worker over the
    // cluster's private service discovery via `imaging.url`.
    const imaging = new sst.aws.Service("Imaging", {
      cluster,
      image: { context: "../invai-imaging" },
      cpu: "2 vCPU",
      memory: "8 GB",
      link: [files, redis],
      environment: {
        S3_BUCKET: files.name,
        REDIS_URL: redisUrl,
      },
    });

    const sharedEnvironment = {
      DATABASE_URL: databaseUrl,
      MIGRATION_DATABASE_URL: databaseUrl,
      REDIS_URL: redisUrl,
      S3_BUCKET: files.name,
      IMAGING_URL: imaging.url,
      BETTER_AUTH_SECRET: betterAuthSecret.value,
      FIELD_ENCRYPTION_KEY: fieldEncryptionKey.value,
      FIELD_ENCRYPTION_KMS_KEY_ARN: fieldEncryptionKmsKey.arn,
      ANTHROPIC_API_KEY: anthropicApiKey.value,
      EASYPOST_API_KEY: easyPostApiKey.value,
      SHOPIFY_API_KEY: shopifyApiKey.value,
      SHOPIFY_API_SECRET: shopifyApiSecret.value,
    };

    // The backend repo has no root Dockerfile-only build context: it links
    // `@invai/contracts` via `link:../invai-contracts`, so the Docker build context is the
    // workspace root (this repo's parent directory) with the Dockerfile path inside it —
    // matches invai-infra/local/docker-compose.yml's `full` profile.
    const backendImage = { context: "..", dockerfile: "invai-backend/Dockerfile" } as const;

    const api = new sst.aws.Service("Api", {
      cluster,
      image: backendImage,
      link: [db, redis, files, ...secrets],
      environment: {
        ...sharedEnvironment,
        BETTER_AUTH_URL: isProd ? "https://api.invai.example" : "http://localhost:3000",
        WEB_ORIGIN: isProd ? "https://app.invai.example" : "http://localhost:5173",
      },
      loadBalancer: {
        rules: [{ listen: "80/http", forward: "3000/http" }],
        health: { "3000/http": { path: "/health" } },
      },
      scaling: { min: isProd ? 2 : 1, max: isProd ? 6 : 1 },
    });

    new sst.aws.Service("Worker", {
      cluster,
      image: backendImage,
      command: ["node", "dist/index.js"],
      link: [db, redis, files, ...secrets],
      environment: sharedEnvironment,
    });

    const web = new sst.aws.StaticSite("Web", {
      path: "../invai-web",
      build: { command: "pnpm build", output: "dist" },
      environment: { VITE_API_URL: api.url },
    });

    const floor = new sst.aws.StaticSite("Floor", {
      path: "../invai-floor",
      build: { command: "pnpm build", output: "dist" },
      environment: { VITE_API_URL: api.url },
    });

    return { api: api.url, web: web.url, floor: floor.url };
  },
});
